            const mockJobs: Career[] = [
                {
                    id: 1,
                    title: "Graphic Designer",
                    department: "Creative",
                    location: "Lahore, Pakistan",
                    type: "Full Time",
                    description: "We are looking for a creative Graphic Designer to join our team. The ideal candidate will have strong creative skills and a portfolio of work which demonstrates their passion for illustrative design and typography. This candidate will have experiences in working with numerous different design platforms such as digital and print forms.",
                    requirements: "Proficient in Adobe Creative Suite (Photoshop, Illustrator, InDesign).\n3+ years of experience in graphic design.\nStrong portfolio showcasing print and digital work.\nAbility to meet deadlines.",
                    posted_date: "2024-01-15"
                },
                {
                    id: 2,
                    title: "Sales Executive",
                    department: "Sales",
                    location: "Lahore, Pakistan",
                    type: "Full Time",
                    description: "Energetic sales executive required with experience in textile. You will be responsible for discovering and pursuing new sales prospects, negotiating deals and maintaining customer satisfaction. If you have excellent communication skills and feel comfortable reaching out to potential customers to demonstrate our services and products through email and phone, we’d like to meet you.",
                    requirements: "Proven experience as a Sales Executive or relevant role.\nProficiency in English.\nExcellent knowledge of MS Office.\nThorough understanding of marketing and negotiating techniques.",
                    posted_date: "2024-01-20"
                }
            ];

            const foundJob = mockJobs.find(j => j.id.toString() === id);
            setJob(foundJob || null);
            setLoading(false);
        }, 500);
    }, [id]);

    if (loading) {
        return (
            <div className={styles.pageWrapper}>
                <div style={{ height: '70vh', display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#c9a14a' }}>
                    Loading...
                </div>
            </div>
        );
    }

    if (!job) {
        return (
            <div className={styles.pageWrapper}>
                <div style={{ height: '70vh', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', color: '#fff' }}>
                    <h2>Job Not Found</h2>
                    <Link href="/careers" style={{ color: '#c9a14a', marginTop: '1rem' }}>Back to Careers</Link>
                </div>
            </div>
        );
    }

    // Parse requirements line by line
    const requirementsList = job.requirements ? job.requirements.split('\n') : [];

    return (
        <div className={styles.pageWrapper}>
            <CursorEffect />
            <PageHeader
                title={job.title}
                breadcrumbs={[
                    { label: "Careers", href: "/careers" },
                    { label: job.title }
                ]}
                backgroundImage="/hero-bg.png"
            />

            <div className={styles.container}>
                <div className={styles.grid}>
                    {/* Main Content */}
                    <main className={styles.details}>
                        <div className={styles.header}>
                            <h1 className={styles.title}>{job.title}</h1>
                            <div className={styles.meta}>
                                <span><Briefcase size={18} className={styles.metaIcon} /> {job.department}</span>
                                <span><MapPin size={18} className={styles.metaIcon} /> {job.location}</span>
                                <span><Clock size={18} className={styles.metaIcon} /> {job.type}</span>
                            </div>
                        </div>

                        <section>
                            <h3 className={styles.sectionTitle}>Job Description</h3>
                            <p className={styles.text}>{job.description}</p>
                        </section>

                        <section>
                            <h3 className={styles.sectionTitle}>Key Requirements</h3>
                            <ul className={styles.requirementsList}>
                                {requirementsList.map((req, index) => (
                                    <li key={index}>{req}</li>
                                ))}
                            </ul>
                        </section>

                        <section>
                            <h3 className={styles.sectionTitle}>What We Offer</h3>
                            <ul className={styles.requirementsList}>
                                <li>Competitive Salary Package</li>
                                <li>Health Insurance</li>
                                <li>Professional Development Environment</li>
                                <li>Annual Leaves</li>
                            </ul>
                        </section>
                    </main>

                    {/* Sidebar */}
                    <aside>
                        <div className={styles.sidebarCard}>
                            <h4 className={styles.sidebarTitle}>Job Overview</h4>

                            <div className={styles.infoItem}>
                                <span className={styles.infoLabel}>Posted Date</span>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                    <Calendar size={14} color="#c9a14a" />
                                    {job.posted_date || 'Recently'}
                                </div>
                            </div>

                            <div className={styles.infoItem}>
                                <span className={styles.infoLabel}>Department</span>
                                {job.department}
                            </div>

                            <div className={styles.infoItem}>
                                <span className={styles.infoLabel}>Location</span>
                                {job.location}
                            </div>

                            <div style={{ marginTop: '2rem' }}>
                                <a href={`mailto:careers@zatraders.pk?subject=Application for ${job.title}`} className={styles.applyButton}>
                                    Apply for this Job
                                </a>
                                <p style={{ fontSize: '0.8rem', color: '#666', textAlign: 'center' }}>
                                    Send your CV via email
                                </p>
                            </div>
                        </div>
                    </aside>
                </div>
            </div>
        </div>
    );
}

import React from 'react';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import ProductCard from '@/components/ProductCard';
import { getProducts as getMockProducts, getAllCategories } from '@/lib/products';
import PageHeader from '@/components/PageHeader';
import styles from './Category.module.css';

// Reusing CSS from PrintedTags if possible or creating new generic one.
// We will create Category.module.css next.

export async function generateStaticParams() {
    const categories = getAllCategories();
    // Pre-render page 1 for each category
    const params = [];
    for (const cat of categories) {
        params.push({ slug: cat, page: '1' });
    }
    return params;
}

async function fetchApiProducts(categorySlug: string) {
    try {
        // Convert slug to likely category name (e.g. "woven-labels" -> "Woven Labels" or just "woven")
        // The API does a partial match ilike %query%
        const searchCanvas = categorySlug.replace(/-/g, ' ');
        const res = await fetch(`/api/public/products?category=${searchCanvas}`, { cache: 'no-store' });
        if (!res.ok) return [];
        return await res.json();
    } catch {
        return [];
    }
}

interface Product {
    id: number | string;
    title: string;
    category: string;
    image?: string;
    imageSrc?: string;
    slug: string;
}

export default async function CategoryPaginationPage({ params }: { params: Promise<{ slug: string, page: string }> }) {
    const { slug, page } = await params;
    const pageNum = parseInt(page);

    if (isNaN(pageNum) || pageNum < 1) {
        notFound();
    }

    // 1. Fetch from API first
    const apiProducts = await fetchApiProducts(slug);

    let products: Product[] = [];
    let totalPages = 1;
    let totalItems = 0;
    const itemsPerPage = 9;

    if (apiProducts.length > 0) {
        // Pagination logic for API data
        totalItems = apiProducts.length;
        totalPages = Math.ceil(totalItems / itemsPerPage);

        const start = (pageNum - 1) * itemsPerPage;
        const end = start + itemsPerPage;

        // Map API data to component Props
        products = apiProducts.slice(start, end).map((p: any) => ({
            id: p.id,
            title: p.title,
            category: p.category,
            image: p.image, // API returns full URL or path
            slug: p.slug
        }));
    } else {
        // 2. Fallback to Mock Data
        const { data, totalPages: mockTotal } = getMockProducts(slug, pageNum, itemsPerPage);
        products = data.map((d) => ({
            id: d.id,
            title: d.title,
            category: d.category,
            categorySlug: d.categorySlug,
            image: d.image,
            slug: d.slug,
            price: d.price,
            description: d.description
        }));
        totalPages = mockTotal;
    }

    if (products.length === 0 && pageNum > 1) {
        // Handle empty page better in real app
    }

    const categoryDisplayName = slug.split('-').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');

    // Sidebar categories
    const allCategories = getAllCategories();

    // Determine background image based on category
    let bgImage = "/hero-bg.png";
    if (slug === 'leather-patches') {
        bgImage = "/LeartherTags/leather-patches-collection.jpg";
    } else if (slug === 'printed-tags' || slug === 'hang-tags') {
        bgImage = "/printed-tags-banner.png";
    } else if (slug === 'paper-bags') {
        bgImage = "/tag-kraft-minimal.png";
    } else if (slug === 'woven-labels') {
        bgImage = "/tag-fabric-white.png";
    }

    return (
        <div>
            <PageHeader
                title={categoryDisplayName}
                breadcrumbs={[
                    { label: categoryDisplayName, href: `/category/${slug}/page/1` },
                    { label: `Page ${pageNum}` }
                ]}
                backgroundImage={bgImage}
            />

            <div className={styles.container}>
                <main>
                    {products.length > 0 ? (
                        <div className={styles.grid}>
                            {products.map((product) => (
                                <ProductCard
                                    key={product.id}
                                    title={product.title}
                                    category={product.category}
                                    imageSrc={product.image || product.imageSrc || ''}
                                    slug={product.slug}
                                    baseUrl={`/category/${slug}`}
                                />
                            ))}
                        </div>
                    ) : (
                        <div className={styles.noProducts}>
                            <p>No products found in this category.</p>
                        </div>
                    )}

                    <div className={styles.pagination}>
                        {pageNum > 1 && (
                            <Link href={`/category/${slug}/page/${pageNum - 1}`} className={styles.pageLink}>&laquo; Prev</Link>
                        )}

                        {Array.from({ length: totalPages || 1 }, (_, i) => i + 1).map((p) => (
                            <Link
                                key={p}
                                href={`/category/${slug}/page/${p}`}
                                className={`${styles.pageLink} ${p === pageNum ? styles.activePage : ''}`}
                            >
                                {p}
                            </Link>
                        ))}

                        {pageNum < totalPages && (
                            <Link href={`/category/${slug}/page/${pageNum + 1}`} className={styles.pageLink}>Next &raquo;</Link>
                        )}
                    </div>
                </main>

                <aside className={styles.sidebar}>
                    <div className={styles.widget}>
                        <h3 className={styles.sidebarHeading}>Categories</h3>
                        <ul className={styles.categoryList}>
                            {allCategories.map((cat) => (
                                <li key={cat}>
                                    <Link
                                        href={`/category/${cat}`}
                                        className={cat === slug ? styles.activeCategory : ''}
                                    >
                                        {cat.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')}
                                    </Link>
                                </li>
                            ))}
                        </ul>
                    </div>

                    <div className={styles.widget} style={{ marginTop: '2rem' }}>
                        <h3 className={styles.sidebarHeading}>Recent Products</h3>
                        <ul className={styles.categoryList}>
                            {/* Keep static for now or fetch recent */}
                            <li><Link href="#">New Arrival: Woven Badge</Link></li>
                            <li><Link href="#">Premium Hang Tags</Link></li>
                            <li><Link href="#">Embossed Leather</Link></li>
                        </ul>
                    </div>
                </aside>
            </div>
        </div>
    );
}

import React from 'react';
import Link from 'next/link';
import ProductCard from '@/components/ProductCard';
import { getAllCategories, getProducts } from '@/lib/products';
import PageHeader from '@/components/PageHeader';
import styles from './page.module.css';

export default function LacePage() {
    const categorySlug = 'lace';

    const allProductsInDb = getProducts(categorySlug, 1, 100).data;
    // Filter to only include the specific items we want for this page, or just use them all.
    // Since we hardcoded the array before, let's try to match the previous list but use the data (images/descriptions) from our DB source.
    const specificSlugs = ['print-woven-lace', 'print-canvas-lace', 'print-ribbon-satin-lace', 'print-lace'];

    // Fallback to hardcoded list if DB finding fails (unlikely)
    const products = specificSlugs.map(slug => {
        const found = allProductsInDb.find(p => p.slug === slug);
        if (found) {
            return {
                ...found,
                imageSrc: found.image // map 'image' to 'imageSrc'
            };
        }
        return null;
    }).filter(p => p !== null) as any[];

    const allCategories = getAllCategories();

    return (
        <div>
            {/* Hero Section */}
            <PageHeader
                title="Lace"
                breadcrumbs={[{ label: "Lace" }]}
                backgroundImage="https://zatraders.pk/wp-content/uploads/2024/06/Print-Canvas-Lace-500x500-1.jpg"
            />

            <div className={styles.container}>
                <main className={styles.mainContent}>
                    {products.length > 0 ? (
                        <div className={styles.grid}>
                            {products.map((product) => (
                                <ProductCard
                                    key={product.id}
                                    title={product.title}
                                    category={product.category}
                                    imageSrc={product.imageSrc}
                                    slug={product.slug}
                                    baseUrl="/category/lace"
                                />
                            ))}
                        </div>
                    ) : (
                        <div className={styles.noProducts}>
                            <p>No lace products found.</p>
                        </div>
                    )}

                    {/* Pagination */}
                    <div className={styles.pagination}>
                        <span className={`${styles.pageLink} ${styles.activePage}`}>1</span>
                    </div>
                </main>

                <aside className={styles.sidebar}>
                    {/* Search Widget */}
                    <div className={styles.widget}>
                        <form className={styles.searchForm}>
                            <input type="text" placeholder="Search..." className={styles.searchInput} />
                            <button type="submit" className={styles.searchButton}>Search</button>
                        </form>
                    </div>

                    {/* Recent Posts Widget */}
                    <div className={styles.widget}>
                        <h3 className={styles.widgetTitle}>Recent Posts</h3>
                        <ul className={styles.categoryList}>
                            {products.map((product) => (
                                <li key={product.id}><Link href={`/category/lace/${product.slug}`}>{product.title}</Link></li>
                            ))}
                            <li><Link href="#">Ribbon Satan Labels</Link></li>
                        </ul>
                    </div>

                    {/* Categories Widget */}
                    <div className={styles.widget}>
                        <h3 className={styles.widgetTitle}>Categories</h3>
                        <ul className={styles.categoryList}>
                            {allCategories.map((cat) => (
                                <li key={cat}>
                                    <Link
                                        href={`/category/${cat}`}
                                        className={cat === categorySlug ? styles.activeCategory : ''}
                                    >
                                        {cat.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')}
                                    </Link>
                                </li>
                            ))}
                        </ul>
                    </div>
                </aside>
            </div>
        </div>
    );
}

